import{_ as e}from"./chunks/dashboard.Cr5kIQaS.js";import{_ as r,c as a,o as n,ag as s}from"./chunks/framework.Ci10AEOF.js";const o="/docs-website/assets/settings_server.BmwvgzPV.png",b=JSON.parse('{"title":"Desktop Administrator","description":"Finding your way around the desktop Administrator, the left menu, the views, the Channel Editor, and the table controls","frontmatter":{"title":"Desktop Administrator","description":"Finding your way around the desktop Administrator, the left menu, the views, the Channel Editor, and the table controls"},"headers":[],"relativePath":"engine/desktop_administrator.md","filePath":"engine/desktop_administrator.md","lastUpdated":1793057853000}'),i={name:"engine/desktop_administrator.md"};function d(h,t,l,c,g,p){return n(),a("div",null,t[0]||(t[0]=[s('<h1 id="desktop-administrator" tabindex="-1">Desktop Administrator <a class="header-anchor" href="#desktop-administrator" aria-label="Permalink to &quot;Desktop Administrator&quot;">​</a></h1><p>Starting the client and logging in are covered in <a href="./accessing_the_administrator.html">Accessing the Administrator</a>. The client connects over HTTPS on port <code>8443</code> by default. A status bar along the bottom of the window shows the server URL, the logged-in user, and the server time with its timezone.</p><p>The <a href="./web_administrator.html">Web Administrator</a> does the same job in a browser.</p><h2 id="the-left-menu" tabindex="-1">The left menu <a class="header-anchor" href="#the-left-menu" aria-label="Permalink to &quot;The left menu&quot;">​</a></h2><p>The left side of the window is a context-sensitive menu.</p><p><img src="'+e+'" alt="The desktop Administrator showing the Dashboard, with the Engine, Dashboard Tasks and Other sections of the left menu"></p><table tabindex="0"><thead><tr><th>View</th><th>What it is</th></tr></thead><tbody><tr><td><strong>Dashboard</strong></td><td>The first screen after logging in. Deployed channels with their state, message counts, and connection activity. Start, stop, pause, and undeploy from here, and open the <a href="./dashboard_and_monitoring.html#message-browser">Message Browser</a> for a channel with <strong>View Messages</strong>. See <a href="./dashboard_and_monitoring.html">Dashboard and Monitoring</a></td></tr><tr><td><strong>Channels</strong></td><td>Every channel configured on the server. Create, delete, import, export, clone, enable, disable, and deploy. Channels can be grouped, and filtered by name or tag</td></tr><tr><td><strong>Users</strong></td><td>Accounts that can reach the server through either administrator, the CLI, or the REST API. See <a href="./user_management.html">User Management</a></td></tr><tr><td><strong>Settings</strong></td><td>Server-wide configuration, covered <a href="#settings">below</a></td></tr><tr><td><strong>Alerts</strong></td><td>Configured alerts with their status and how often each has fired. See <a href="./alerts_and_notifications.html">Alerts and Notifications</a></td></tr><tr><td><strong>Events</strong></td><td>A searchable log of user actions and system events, filterable by date, severity, user, and outcome, exportable to a comma-separated text file in the server&#39;s exports directory. See <a href="./dashboard_and_monitoring.html#event-browser">the Event Browser</a></td></tr><tr><td><strong>Extensions</strong></td><td>Installed plugins and connectors with their status, author, and version, and where you enable or disable them. See the <a href="./plugins.html">Plugin Guide</a></td></tr></tbody></table><h2 id="channel-editor" tabindex="-1">Channel Editor <a class="header-anchor" href="#channel-editor" aria-label="Permalink to &quot;Channel Editor&quot;">​</a></h2><p>Opening a channel from the Channels view gives you a tabbed workspace:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Summary</strong></td><td>Name, description, data types, initial state, storage and pruning settings, tags, dependencies, and custom metadata columns</td></tr><tr><td><strong>Source</strong></td><td>The source connector and its settings</td></tr><tr><td><strong>Destinations</strong></td><td>One or more destination connectors, each with its own filter and transformer</td></tr><tr><td><strong>Scripts</strong></td><td>Channel-level Deploy, Undeploy, Preprocessor, and Postprocessor scripts</td></tr></tbody></table><p>Within Source and Destinations you can open two editors:</p><ul><li><strong>Filter Editor</strong>, for rules (Rule Builder, JavaScript, External Script, <a href="./glossary.html#iterator">Iterator</a>) joined by AND/OR. A message that matches is accepted, and one that does not is filtered.</li><li><strong>Transformer Editor</strong>, for a sequence of steps (<a href="./glossary.html#mapper">Mapper</a>, <a href="./glossary.html#message-builder">Message Builder</a>, JavaScript, External Script, XSLT Step, Iterator, <a href="./glossary.html#destination-set">Destination Set Filter</a>). Dragging a field between the inbound and outbound message trees generates a mapping step.</li></ul><p>A connector&#39;s filter and transformer are compiled into one script. A variable a filter rule assigns without <code>var</code> is still there in the transformer; one declared with <code>var</code> stays inside the rule. See <a href="./filters_and_transformers.html">Filters and Transformers</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The tabs cover server-wide options:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td>Environment name and server name, both of which appear in the title bar, plus default background color, auto logout, clear global map on redeploy, default queue buffer size, default metadata columns, SMTP configuration, and login notification and consent</td></tr><tr><td><strong>Administrator</strong></td><td>UI preferences such as dashboard refresh interval and confirmation dialog behavior</td></tr><tr><td><strong>Tags</strong></td><td>Create and manage channel tags</td></tr><tr><td><strong>Configuration Map</strong></td><td>Key-value pairs readable from channel scripts at runtime</td></tr><tr><td><strong>Database Tasks</strong></td><td>Database cleanup and index tasks. See <a href="./data_pruning_and_maintenance.html#database-tasks">Database tasks</a></td></tr><tr><td><strong>Resources</strong></td><td>Custom class-path library resources available to channels</td></tr><tr><td><strong>Data Pruner</strong></td><td>Global settings for automatic message pruning</td></tr></tbody></table><p><img src="'+o+'" alt="The Server tab of Settings, with the General, Channel, Email and Notification sections"></p><p>A plugin that ships a settings panel adds its own tab here, named for the plugin.</p><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><p>Below the view buttons, a fixed section of the left menu is available from every view:</p><table tabindex="0"><thead><tr><th>Task</th><th>Description</th></tr></thead><tbody><tr><td><strong>Notifications</strong></td><td>OIE release announcements from the project&#39;s GitHub repository. When there are unread items the link reads <strong>Notifications (n)</strong></td></tr><tr><td><strong>View User API</strong></td><td>Opens the User API (Javadoc) in your browser</td></tr><tr><td><strong>View Client API</strong></td><td>Opens the REST API documentation in your browser</td></tr><tr><td><strong>Visit homepage</strong></td><td>Opens the OIE project repository</td></tr><tr><td><strong>Report Issue</strong></td><td>Opens the project&#39;s issue tracker</td></tr><tr><td><strong>Help</strong></td><td>Opens the OIE GitHub discussions</td></tr><tr><td><strong>About</strong></td><td>Version, build date, server ID, Java version, and third-party acknowledgements</td></tr><tr><td><strong>Logout</strong></td><td>Ends the session and returns to the login screen</td></tr></tbody></table><h2 id="working-with-tables" tabindex="-1">Working with tables <a class="header-anchor" href="#working-with-tables" aria-label="Permalink to &quot;Working with tables&quot;">​</a></h2><p>Most screens present data in tables that behave the same way:</p><ul><li>Drag a column header to move it; adjacent columns shift.</li><li>Right-click the header row to show or hide columns, or use the table control icon at its top right.</li><li>Click a header to sort ascending, again for descending. Not every table sorts.</li><li>Click the plus or minus beside a row to expand or collapse it, or right-click the header for Expand All and Collapse All.</li><li>Shift-click for a contiguous range of rows, Ctrl-click (Cmd on macOS) for individual ones.</li><li>Press Delete to remove a selected row, where the table allows it.</li></ul>',24)]))}const f=r(i,[["render",d]]);export{b as __pageData,f as default};
